NEW_FILES = {'migrations/migrate_grocery_gondolas.py': '#!/usr/bin/env python3\n"""\nmigrate_grocery_gondolas.py  --  a supermarket\'s shelves sell what its markers say (0.278.0)\n=========================================================================================\nOne-shot, idempotent migration over specs/*.json. Furnish makes a supermarket\'s gondolas Zoo 1.133.0\'s\n`snack_gondola` form `grocery`, each the variant of its line and turned so the faces either side of a lane sell the\ntwo categories its marker prints (`level_design.stock_supermarket_gondolas`). The library is a fixed point of its\nfurnishing pass, so every spec with a supermarket\'s sales floor is refurnished (`migrate_furnish_recipes.migrate`); no\nother spec is touched.\n\n`lf_*` specs are Level Factory\'s per-run transients and are skipped.\n\n    python migrations/migrate_grocery_gondolas.py            # write specs/\n    python migrations/migrate_grocery_gondolas.py --check    # report only; exit 1 if any would change\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\nsys.path.insert(0, os.path.join(HERE, "migrations"))\n\nimport level_design  # noqa: E402\nimport migrate_furnish_recipes  # noqa: E402\n\n\ndef _supermarket(d):\n    b = level_design.club_building_id(d)\n    return any(level_design.is_supermarket_floor(r, b) for r in d.get("rooms") or [])\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = os.path.join(HERE, "specs")\n    changed = 0\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not _supermarket(d):\n            continue\n        before = json.dumps(d, indent=1) + "\\n"\n        migrate_furnish_recipes.migrate(d)\n        after = json.dumps(d, indent=1) + "\\n"\n        if after == before:\n            continue\n        changed += 1\n        n = sum(1 for v in d["volumes"] if str(v.get("name", "")).startswith("gondola_")\n                and v.get("form") == "grocery")\n        print(f"[grocery_gondolas] {os.path.basename(p)}: {n} grocery gondola(s)")\n        if not check:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(after)\n    verb = "would change" if check else "refurnished"\n    print(f"[grocery_gondolas] {changed} spec(s) {verb}")\n    return 1 if check and changed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_grocery_gondolas.py': '"""0.278.0 -- a supermarket\'s shelves sell what the markers over them say.\n\nThe walker\'s grocery comps (the factory\'s docs/reference/GROCERY_STORE_COMPS.md); in the walker\'s level the\nsupermarket\'s gondolas sold the convenience store\'s chips under markers that said CEREAL and CANNED VEG. Zoo 1.133.0\'s\n`snack_gondola` form `grocery` sells, on each face, one of the 24 categories the markers print: face -Y of the\ngondola on line v the second category of lane v - 1, face +Y the first of lane v (`grocery_faces`). So furnish makes\nevery gondola of a supermarket\'s floor that form, the variant of its line, its module\'s +Y toward the higher lane\n(`stock_supermarket_gondolas`). Lane j\'s marker is variant j: its two categories are then the +Y face of line j and the\n-Y face of line j + 1.\n\nFAILS ON 0.277.0: `stock_supermarket_gondolas` and `_gondola_lines` do not exist, and the library\'s gondolas are the\nsnack form.\n"""\nimport copy\nimport glob\nimport json\nimport os\nimport sys\n\nimport pytest\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\n\nimport level_design as L  # noqa: E402\n\n\ndef _supermarkets():\n    out = []\n    for p in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        d = json.load(open(p, encoding="utf-8"))\n        b = L.club_building_id(d)\n        for r in d.get("rooms") or []:\n            if L.is_supermarket_floor(r, b):\n                out.append((os.path.basename(p), d, r))\n    return out\n\n\ndef test_the_library_has_supermarkets_to_hold():\n    names = {n for n, _d, _r in _supermarkets()}\n    assert {"supermarket_a01.json", "supermarket_a02.json", "supermarket_a03.json"} <= names\n\n\ndef test_every_gondola_is_the_grocery_form_of_its_line_turned_to_the_lane_after():\n    for name, d, r in _supermarkets():\n        along_y, lines = L._gondola_lines(d, r)\n        assert len(lines) >= 2, name\n        want = 90.0 if along_y else 0.0\n        for n, line in enumerate(lines):\n            for v in line["vols"]:\n                assert v.get("form") == "grocery", (name, v["name"])\n                assert int(v.get("variant", 0) or 0) == n % L._GROCERY_LINES, (name, v["name"], n)\n                assert abs(L._plus_y_plan(v) - want) < 1e-6, (name, v["name"], L._plus_y_plan(v))\n\n\ndef test_a_lanes_marker_and_the_faces_either_side_of_it_agree():\n    """Lane j between line j and line j + 1: its marker is variant j, the +Y face of line j sells its first\n    category and the -Y face of line j + 1 its second -- variants j and j + 1. Every lane of the library takes a\n    marker, which that pairing needs (a skipped lane would renumber the markers after it)."""\n    for name, d, r in _supermarkets():\n        _along, lines = L._gondola_lines(d, r)\n        markers = L.aisle_markers(d, r)\n        assert len(markers) == len(lines) - 1, (name, len(markers), len(lines))\n        hung = sorted((v for v in d["volumes"] if str(v.get("name", "")).startswith("aisle_sign_")\n                       and v.get("form") == "grocery"), key=lambda v: int(v.get("variant", 0) or 0))\n        assert [int(v.get("variant", 0) or 0) for v in hung] == list(range(len(lines) - 1)), name\n        for j in range(len(lines) - 1):\n            lo = {int(v.get("variant", 0) or 0) for v in lines[j]["vols"]}\n            hi = {int(v.get("variant", 0) or 0) for v in lines[j + 1]["vols"]}\n            assert lo == {j} and hi == {j + 1}, (name, j, lo, hi)\n\n\ndef test_stocking_is_a_fixed_point_and_turns_a_backward_gondola():\n    _name, d, r = next(s for s in _supermarkets() if s[0] == "supermarket_a02.json")\n    d = copy.deepcopy(d)\n    assert L.stock_supermarket_gondolas(d, r) == 0\n    along_y, lines = L._gondola_lines(d, r)\n    v = lines[1]["vols"][0]\n    v["rot_z"] = (float(v.get("rot_z", 0.0) or 0.0) + 180.0) % 360.0\n    v["variant"] = 7\n    v.pop("form")\n    assert L.stock_supermarket_gondolas(d, r) == 1\n    assert v.get("form") == "grocery" and int(v.get("variant", 0) or 0) == 1\n    assert abs(L._plus_y_plan(v) - (90.0 if along_y else 0.0)) < 1e-6\n    assert L.stock_supermarket_gondolas(d, r) == 0\n\n\ndef test_the_slots_carry_the_form_and_the_line():\n    """What Zoo is asked for: the slot records the volume\'s form and variant, and the turn that points +Y at the\n    lane after."""\n    name, d, r = next(s for s in _supermarkets() if s[0] == "supermarket_a01.json")\n    _along, lines = L._gondola_lines(d, r)\n    by_name = {v["name"]: n for n, line in enumerate(lines) for v in line["vols"]}\n    p = os.path.join(HERE, "build", "supermarket_a01.slots.json")\n    if not os.path.exists(p):\n        pytest.skip("supermarket_a01 is not built")\n    slots = json.load(open(p, encoding="utf-8"))["slots"]\n    got = {s["slot_id"]: s for s in slots if s["slot_id"] in by_name}\n    assert set(got) == set(by_name), name\n    for sid, n in by_name.items():\n        assert got[sid]["form"] == "grocery" and got[sid]["variant"] == n, (sid, got[sid]["form"], got[sid]["variant"])\n        assert got[sid]["transform"]["rot_y"] == 90.0, (sid, got[sid]["transform"]["rot_y"])\n'}
CHANGELOG = "## [0.278.0] - a supermarket's shelves sell what the markers over them say\n\nThe walker's grocery comps (the factory's docs/reference/GROCERY_STORE_COMPS.md). In the walker's level the\nsupermarket's gondolas sold the convenience store's chips under markers that said CEREAL and CANNED VEG (0.276.0).\nZoo 1.133.0's `snack_gondola` form `grocery` sells, on each face, one of the 24 categories the markers print.\n\n### Added\n- **`stock_supermarket_gondolas(spec, room)`.** Furnish makes every gondola on a supermarket's floor, authored or\n  laid, Zoo's grocery form:\n  - its VARIANT is its line's index, low end of the cross axis first, as the markers number their lanes;\n  - it is turned half round where its module's +Y points to the lower lane. A gondola is an island shopped on both\n    sides, so the turn moves nothing it collides with.\n  - In Zoo's rule, face -Y of line v sells the second category of lane v - 1 and face +Y the first of lane v. So\n    lane j's two categories are on the +Y face of line j and the -Y face of line j + 1, under marker j.\n  - Twelve lines sell all 24 categories; a thirteenth starts round again.\n- **`_plus_y_plan(v)`**: where a gondola's module +Y points in plan. The slot's turn\n  (`prop_species.long_axis_first`, plus the volume's `rot_z`) takes the module's +X to plan +X at 0 degrees, -Y at\n  90, -X at 180 and +Y at 270 (the composer's measured convention), so its +Y goes to plan +Y, +X, -Y and -X.\n- **`migrations/migrate_grocery_gondolas.py`** refurnishes the three supermarkets:\n  - a01: 5 gondolas;\n  - a02: 10 gondolas. Its laid runs' variants, drawn for variety, are now their lines'. The two runs on line 2 that\n    stood at 180 degrees now stand at 0, their +Y toward the lane after.\n  - a03: 4 gondolas.\n\n### Changed\n- **`_gondola_lines(spec, room)`**: `aisle_markers`' grouping of the gondolas into lines, moved out whole so the\n  markers and the stock read one grouping. Each line now also carries its volumes. Every marker is where it was.\n\n### Tests\n- `tests/test_grocery_gondolas.py` (4 of 5 fail on 0.277.0; the first holds the library's three supermarkets):\n  - every gondola is the grocery form of its line, its +Y toward the lane after;\n  - a lane's marker and the faces either side of it agree. Every lane of the library takes a marker, which the\n    pairing needs: a skipped lane would renumber the markers after it.\n  - stocking is a fixed point, and turns a backward gondola back;\n  - the slots carry the form, the line and the turn.\n\n"
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.277.0', 'Deli Counter 0.278.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
